import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    names = data[1:1 + 3 * n:3]
    xs = [int(v) for v in data[2:2 + 3 * n:3]]
    ys = [int(v) for v in data[3:3 + 3 * n:3]]
    m = int(data[1 + 3 * n])
    queries = data[2 + 3 * n:2 + 3 * n + m]
    best = [None] * n  # (distance, name)

    def process(keys, coords):
        groups = {}
        for i in range(n):
            groups.setdefault(keys[i], []).append((coords[i], names[i], i))
        for lst in groups.values():
            lst.sort()
            clusters = []  # [coord, [names sorted], [indices]]
            for c, nm, i in lst:
                if clusters and clusters[-1][0] == c:
                    clusters[-1][1].append(nm)
                    clusters[-1][2].append(i)
                else:
                    clusters.append([c, [nm], [i]])
            for k, (c, nms, idxs) in enumerate(clusters):
                for nm, i in zip(nms, idxs):
                    cands = []
                    if len(nms) > 1:
                        cands.append((0, nms[0] if nms[0] != nm else nms[1]))
                    if k > 0:
                        cands.append((c - clusters[k - 1][0], clusters[k - 1][1][0]))
                    if k + 1 < len(clusters):
                        cands.append((clusters[k + 1][0] - c, clusters[k + 1][1][0]))
                    for cand in cands:
                        if best[i] is None or cand < best[i]:
                            best[i] = cand

    process(xs, ys)
    process(ys, xs)
    index = {names[i]: i for i in range(n)}
    out = []
    for q in queries:
        b = best[index[q]]
        out.append('NONE' if b is None else b[1])
    print('\n'.join(out))

main()

