    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer tk = new StringTokenizer(all.toString());
        int n = Integer.parseInt(tk.nextToken());
        String[] names = new String[n];
        long[] xs = new long[n], ys = new long[n];
        for (int i = 0; i < n; i++) {
            names[i] = tk.nextToken();
            xs[i] = Long.parseLong(tk.nextToken());
            ys[i] = Long.parseLong(tk.nextToken());
        }
        int m = Integer.parseInt(tk.nextToken());
        String[] queries = new String[m];
        for (int i = 0; i < m; i++) queries[i] = tk.nextToken();
        String[] res = closestStraightCity(names, xs, ys, queries);
        StringBuilder sb = new StringBuilder();
        for (String s : res) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
